// Recompiled SPU image descriptors (generated by tools/spu_recomp.py into build/gen/spu_recomp.cpp).
#pragma once

#include <cstdint>

struct SpuThread;

typedef uint64_t (*SpuNativeFn)(SpuThread& t, uint32_t pc, uint8_t* range_state);

struct SpuImageDesc {
    const char* name;
    uint32_t base, end;             // LS span covered by the snapshot
    const uint8_t* bytes;           // LS bytes [base, end) as captured from the image
    const uint32_t* ranges;         // code ranges: [start, end) pairs
    uint32_t range_count;
    const int16_t* range_of_word;   // per word in [base, end): range index or -1
    const uint64_t* entry_bitmap;   // 0x10000 bits over the LS: dispatch entries
    SpuNativeFn fn;
};

extern const SpuImageDesc g_spu_images[];
extern const uint32_t g_spu_image_count;

// validates (memcmp against the snapshot) and caches the state of one code range
bool spu_validate_range(SpuThread& t, uint32_t img, uint32_t range);
void spu_native_set_enabled(bool on);  // --no-spu-native turns recompiled code off (debugging)
